    # ---------------------------------------------------------------- runtime
    def _ev(self, name, kind=None):
        """Callback that calls handler *name* if it exists (with EventArgs if kind)."""
        def call(*a):
            fn = getattr(self, name, None)
            if fn is not None:
                return fn(EventArgs(a[0] if a else None)) if kind else fn()
        return call

    def _bind(self, widget, seq, name, kind=None, chars_only=False, own=False):
        def call(ev):
            if chars_only and not ev.char:
                return
            if own and ev.widget is not widget:
                return
            fn = getattr(self, name, None)
            if fn is not None:
                return fn(EventArgs(ev)) if kind else fn()
        widget.bind(seq, call, add="+")

    def _bind_tabs(self, nb, name):
        """SelectedIndexChanged for a TabControl (only when the page really changes)."""
        nb._rad_last = nb.index("current") if nb.tabs() else -1

        def changed(_e):
            i = nb.index("current") if nb.tabs() else -1
            if i != nb._rad_last:
                nb._rad_last = i
                fn = getattr(self, name, None)
                if fn is not None:
                    fn()
        nb.bind("<<NotebookTabChanged>>", changed, add="+")

    def _on_close(self):
        e = EventArgs()
        fn = getattr(self, "Form1_FormClosing", None)
        if fn is not None:
            fn(e)
        if e.Cancel:
            return
        self.root.destroy()
        fn = getattr(self, "Form1_FormClosed", None)
        if fn is not None:
            fn()

    def __getattr__(self, name):
        """Unknown attributes go to the window (self.after, self.destroy, ...)."""
        if name == "root" or name.startswith("__"):
            raise AttributeError(name)
        return getattr(self.root, name)

    def _res(self, path):
        return os.path.join(os.path.dirname(os.path.abspath(__file__)), path)

    def show(self):
        self.root.mainloop()
